{"command": "$ErrorActionPreference='Stop'
$ws='C:\Users\Admin\Documents\deepseek-harness\default-workspace'
$h=@{'User-Agent'='dsh-agent'}
New-Item -ItemType Directory -Force -Path "$ws\skills","$ws\refs" | Out-Null
function Save-Dir([string]$api,[string]$dest){
  New-Item -ItemType Directory -Force -Path $dest | Out-Null
  $items = Invoke-RestMethod -Uri $api -Headers $h -TimeoutSec 40
  foreach($it in $items){
    if($it.type -eq 'dir'){ Save-Dir $it.url (Join-Path $dest $it.name) }
    elseif($it.type -eq 'file'){ Invoke-WebRequest -Uri $it.download_url -Headers $h -OutFile (Join-Path $dest $it.name) -TimeoutSec 40 }
  }
}
foreach($s in @('paper-lookup','literature-review')){
  Save-Dir "https://api.github.com/repos/K-Dense-AI/scientific-agent-skills/contents/skills/$s" "$ws\skills\$s"
  "skill $s files: " + ((Get-ChildItem "$ws\skills\$s" -Recurse -File).Count)
}
$zip = Join-Path $env:TEMP 'rootguard.zip'
if(-not (Test-Path "$ws\refs\rootguard\README.md")){
  Invoke-WebRequest -Uri 'https://codeload.github.com/danshumaan/rootguard/zip/refs/heads/main' -OutFile $zip -TimeoutSec 120
  Expand-Archive -Path $zip -DestinationPath "$ws\refs\_tmp_rg" -Force
  Move-Item "$ws\refs\_tmp_rg\rootguard-main" "$ws\refs\rootguard" -Force
  Remove-Item "$ws\refs\_tmp_rg" -Recurse -Force
}
"rootguard files: " + ((Get-ChildItem "$ws\refs\rootguard" -Recurse -File).Count)
Get-ChildItem "$ws\refs\rootguard" | Select-Object -ExpandProperty Name", "description": "Download skills and RootGuard repository", "justification": "工作区的 workspace-write 沙箱下 PowerShell 无法启动，只能以完全访问权限下载用户要求的 GitHub skill 与 RootGuard 代码仓库到工作目录。", "sandbox_permissions": "danger-full-access", "timeoutMs": 300000}

